namespace Hugo.Connectors.Abstractions
{
    /// <summary>
    /// Who produced a knowledge entry.
    /// </summary>
    public enum KnowledgeSourceEnum
    {
        /// <summary>
        /// Written or edited by a person in the dashboard or API.
        /// </summary>
        Operator = 0,

        /// <summary>
        /// Generated by a model from crawled structure and samples.
        /// </summary>
        Generated = 1,

        /// <summary>
        /// Recorded by an agent during a conversation (for example a discovered join path or business rule).
        /// </summary>
        Agent = 2,

        /// <summary>
        /// Derived deterministically from structure (for example inferred relationships).
        /// </summary>
        Derived = 3
    }
}
